/* app.js — pages, charts and settings (patched from the approved prototype) */
const EMPTY={types:['Residential','Commercial'],cats:['Residential'],subs:['Other commercial'],subfull:['Other commercial'],svcs:Engine.SVCS,marlas:[],areas:['Other areas'],zones:Engine.ZONES,rows:{t:[],c:[],s:[],v:[],m:[],a:[],z:[],st:[],b:[],p:[]},top:[],meta:{master:0,active:0,inactive:0,billrows:0,matched:0,billonly:0,masteronly:0,masteronly_active:0,neg:0,negsum:0,f1:'—',f2:'—',period:'—'}};
let D=EMPTY,R=D.rows,N=0,M=D.meta,Z0=[],ZO={},ZON={},AZ=[],ALL=[],CON=[],CMAP=new Map(),MG={cols:[],colSrc:[],rows:[]},DERIVED=[],FILES=[],HAS=false;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const fN=n=>Math.round(n).toLocaleString('en-US');
const PREF={num:'M'};const fM=v=>{const a=Math.abs(v),s=v<0?'-':'';if(PREF.num=='L')return a>=1e7?s+'Rs '+(a/1e7).toFixed(2)+' Cr':a>=1e5?s+'Rs '+(a/1e5).toFixed(2)+' Lac':s+'Rs '+fN(a);return a>=1e6?s+'Rs '+(a/1e6).toFixed(2)+'M':a>=1e3?s+'Rs '+(a/1e3).toFixed(a>=1e5?0:1)+'K':s+'Rs '+Math.round(a)};
const pc=(a,b)=>b?(100*a/b).toFixed(1)+'%':'0%';
const TC=['var(--a1)','var(--a4)'];
const SC=['var(--a6)','var(--a2)','var(--a3)','var(--a4)','var(--a5)','var(--mu)','var(--mu)'];
const ICON={users:'<path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM23 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8"/>',bill:'<path d="M14 3H6a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V8zM14 3v5h5M9 13h6M9 17h6"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10M9.5 9.5C9.5 8.5 10.6 8 12 8s2.5.6 2.5 1.6S13.4 11 12 11s-2.5.5-2.5 1.5S10.6 14 12 14s2.5-.5 2.5-1.5"/>',due:'<path d="M12 8v4l3 2"/><circle cx="12" cy="12" r="9"/>'};
const ic=k=>`<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${ICON[k]}</svg>`;
/* tooltip */
const tip=$('#tip');
document.addEventListener('mousemove',e=>{const t=e.target.closest('[data-tip]');if(t){tip.innerHTML=t.dataset.tip;tip.style.opacity=1;tip.style.left=Math.min(e.clientX+14,innerWidth-270)+'px';tip.style.top=(e.clientY+14)+'px'}else tip.style.opacity=0});
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove('on'),2200)}
/* theme */
function setTheme(t){document.documentElement.dataset.theme=t;$$('.themes button').forEach(b=>b.classList.toggle('on',b.dataset.t===t));try{localStorage.setItem('wk-theme',t)}catch(e){}}
$$('.themes button').forEach(b=>b.onclick=()=>setTheme(b.dataset.t));
try{setTheme(localStorage.getItem('wk-theme')||'ocean')}catch(e){setTheme('ocean')}
/* chart helpers */
function bars(items,o={}){ // items:{n,v,u?,c,tip,sub}
  const mx=Math.max(1,...items.map(i=>Math.max(i.v,i.u||0)));
  return `<div class="bl ${o.scroll?'scroll':''}">`+items.map(i=>`<div class="br" data-tip="${i.tip||''}"><span class="n" title="${i.n}">${i.n}</span><span class="t">${i.u!=null?`<i class="u" style="width:${100*i.u/mx}%;background:${i.c}"></i>`:''}<i class="${i.u!=null?'f':''}" style="width:${100*i.v/mx}%;background:${i.c}"></i></span><span class="x">${i.x}${i.s?`<s>${i.s}</s>`:''}</span></div>`).join('')+'</div>'}
function donut(segs,cv,cs,size=148){const tot=segs.reduce((a,b)=>a+b.v,0)||1,r=size/2-12,C=2*Math.PI*r;let off=0;
  const arcs=segs.map(s=>{const l=C*s.v/tot;const e=`<circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="${s.c}" stroke-width="16" stroke-dasharray="${Math.max(0,l-2)} ${C-Math.max(0,l-2)}" stroke-dashoffset="${-off}" transform="rotate(-90 ${size/2} ${size/2})" data-tip="${s.n}: ${s.t}"/>`;off+=l;return e}).join('');
  return `<div class="ring" style="width:${size}px;height:${size}px"><svg width="${size}" height="${size}"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="var(--track)" stroke-width="16"/>${arcs}</svg><div class="c"><div><b>${cv}</b><span>${cs}</span></div></div></div>`}
const legend=segs=>`<div class="leg">`+segs.map(s=>`<div><i style="background:${s.c}"></i><span>${s.n}</span><b>${s.t}</b></div>`).join('')+'</div>';
const seg=(id,opts,cur)=>`<div class="seg" data-seg="${id}">`+opts.map(([k,l])=>`<button data-k="${k}" class="${k===cur?'on':''}">${l}</button>`).join('')+'</div>';
const card=(span,f,title,sub,right,body,id)=>`<div class="card ${span}" ${id?`id="${id}"`:''}><div class="ch"><div><h3>${title}</h3>${sub?`<div class="sub">${sub}</div>`:''}</div><div class="r">${right||''}${f?`<span class="ftag">${f}</span>`:''}</div></div><div class="cb">${body}</div></div>`;
/* state + filtering */
const F={t:'',c:'',z:'',v:''};const UI={f6:'c',f7:'c',f8:0,f9:1,f10:0,f17:'n',f13:'n'};
let IX=[];
function filt(){IX=[];for(let i=0;i<N;i++){if(F.t!==''&&R.t[i]!=F.t)continue;if(F.c!==''&&R.c[i]!=F.c)continue;if(F.z!==''&&R.z[i]!=F.z)continue;if(F.v!==''&&R.v[i]!=F.v)continue;IX.push(i)}}
function grp(key,len,ix=IX,sel){const o=Array.from({length:len},()=>({n:0,b:0,p:0,paid:0}));for(const i of ix){const k=R[key][i];if(k<0)continue;const g=o[k];g.n++;g.b+=R.b[i];g.p+=R.p[i];if(R.p[i]>0)g.paid++}return o}
function fillSel(id,arr,all){const s=$(id);s.innerHTML=`<option value="">${all}</option>`+arr.map((x,i)=>`<option value="${i}">${x}</option>`).join('')}
fillSel('#fT',D.types,'All types');fillSel('#fZ',D.zones,'All zones');
[['#fT','t'],['#fZ','z']].forEach(([s,k])=>$(s).onchange=e=>{F[k]=e.target.value;renderDash()});
$('#fReset').onclick=()=>{Object.keys(F).forEach(k=>F[k]='');$$('.fbar select').forEach(s=>s.value=s.id==='fP'?s.value:'');renderDash()};
$('#tagsChk').onchange=e=>$('#dash').classList.toggle('hide-tags',!e.target.checked);
/* dashboard */
function renderDash(){
  filt();$('#fCount').textContent=fN(IX.length)+' consumers in view';
  let B=0,P=0,pd=0,act=0,ina=0,unm=0;for(const i of IX){B+=R.b[i];P+=R.p[i];if(R.p[i]>0)pd++;const s=R.st[i];s==0?act++:s==1?ina++:unm++}
  const byT=grp('t',2),byC=grp('c',D.cats.length),byS=grp('s',D.subs.length),byV=grp('v',D.svcs.length),byA=grp('a',D.areas.length),byZ=grp('z',4),byM=grp('m',D.marlas.length);
  const kp=(l,v,d,k)=>`<div class="card kpi s3"><div class="l">${l}<span class="ic">${ic(k)}</span><span class="ftag">F1</span></div><div class="v">${v}</div><div class="d">${d}</div></div>`;
  const h=[];
  h.push(kp('Total consumers',fN(IX.length),`<b>${fN(act)}</b> active · ${fN(ina)} inactive`,'users'));
  h.push(kp('Billed amount',fM(B),`${D.meta.period} · incl. arrears`,'bill'));
  h.push(kp('Collected amount',fM(P),`<b>${pc(P,B)}</b> of billed`,'coin'));
  h.push(kp('Due / balance',fM(B-P),`${fN(IX.length-pd)} consumers have not paid`,'due'));
  /* F2 */
  const tseg=(v)=>D.types.map((n,i)=>({n,v:v(i),c:TC[i],t:fN(v(i))}));
  const s2=tseg(i=>byT[i].n);
  h.push(card('s4','F2','Consumers by type','',``,`<div class="dn">${donut(s2,fN(IX.length),'consumers')}${legend(s2)}</div>`));
  /* F3 */
  const c3=D.cats.map((n,i)=>({n:i==0?'Residential':'Category '+n,v:byC[i].n,i})).filter(x=>x.i>0&&x.v>0).map(x=>({...x,c:'var(--a1)',x:fN(x.v),tip:fN(x.v)+' consumers'}));
  h.push(card('s4','F3','Consumers by category','Commercial categories',``,c3.length?bars(c3,{scroll:1}):'<div class="empty">No commercial consumers in this view</div>'));
  /* F4 */
  const c4=D.subs.map((n,i)=>({n,v:byS[i].n,tip:D.subfull[i]+': '+fN(byS[i].n)})).filter(x=>x.v>0).sort((a,b)=>(a.n=='Other commercial')-(b.n=='Other commercial')||b.v-a.v).map(x=>({...x,c:'var(--a2)',x:fN(x.v)}));
  h.push(card('s4','F4','Consumers by sub-category','Commercial · top 12',``,c4.length?bars(c4,{scroll:1}):'<div class="empty">No sub-categories in this view</div>'));
  /* F5 */
  const s5=D.types.map((n,i)=>({n,v:byT[i].p,c:TC[i],t:fM(byT[i].p)}));
  h.push(card('s4','F5','Collection by type','',``,`<div class="dn">${donut(s5,fM(P),'collected')}<div style="flex:1;min-width:150px">${bars(D.types.map((n,i)=>({n,v:byT[i].p,u:byT[i].b,c:TC[i],x:fM(byT[i].p),s:'of '+fM(byT[i].b),tip:pc(byT[i].p,byT[i].b)+' collected'})))}</div></div>`));
  /* F6 / F7 */
  const cm=(g,names,full,key)=>{const mode=UI[key];return names.map((n,i)=>{const val=mode=='c'?g[i].p:mode=='b'?g[i].b:g[i].n;return{n:(key=='f6'?(i==0?'Residential':'Category '+n):n),v:val,u:mode=='c'?g[i].b:null,c:'var(--a1)',x:mode=='n'?fN(val):fM(val),s:mode=='c'?pc(g[i].p,g[i].b):mode=='n'?fM(g[i].b)+' billed':null,tip:(full?full[i]:n)+'<br>'+fN(g[i].n)+' consumers · Billed '+fM(g[i].b)+' · Collected '+fM(g[i].p),b:g[i].b,cn:g[i].n,k:i}}).filter(x=>(mode=='n'?x.cn>0:x.b>0)&&(key!='f6'||x.k>0))};
  const sg=seg('f6',[['c','Collection'],['b','Billed'],['n','Consumers']],UI.f6);
  h.push(card('s4','F6','Collection by category','',sg,bars(cm(byC,D.cats,null,'f6'),{scroll:1}),'f6'));
  h.push(card('s4','F7','Collection by sub-category','Commercial',seg('f7',[['c','Collection'],['b','Billed'],['n','Consumers']],UI.f7),bars(cm(byS,D.subs,D.subfull,'f7').sort((a,b)=>(a.n=='Other commercial')-(b.n=='Other commercial')||b.v-a.v),{scroll:1}),'f7'));
  /* F8 */
  const ty=UI.f8,vs=D.svcs.map((n,i)=>({n,v:0,c:SC[i],t:'0',i}));
  for(const i of IX)if(R.t[i]==ty)vs[R.v[i]].v++;vs.forEach(s=>s.t=fN(s.v));const vsf=vs.filter(s=>s.v>0),tt=vsf.reduce((a,b)=>a+b.v,0);
  h.push(card('s6','F8','Service by type',ty?'Commercial':'Residential',`<div class="seg" data-seg="f8"><button data-k="0" class="${ty==0?'on':''}">Residential</button><button data-k="1" class="${ty==1?'on':''}">Commercial</button></div>`,tt?`<div class="dn">${donut(vsf,fN(tt),'connections')}${legend(vsf.map(s=>({...s,t:s.t+' · '+pc(s.v,tt)})))}</div>`:'<div class="empty">No connections in this view</div>','f8'));
  /* F9 */
  const catsAvail=D.cats.map((n,i)=>[i,i==0?'Residential':'Category '+n]);
  const rowsF9=D.svcs.map((n,k)=>{let c=0,a=0;for(const i of IX)if(R.c[i]==UI.f9&&R.v[i]==k){c++;a+=R.b[i]}return{n,c,a,k}}).filter(x=>x.c);
  const t9=(rs)=>rs.length?`<table><thead><tr><th>Service</th><th class="n">Connections</th><th class="n">Amount</th></tr></thead><tbody>${rs.map(x=>`<tr><td><span style="display:inline-block;width:9px;height:9px;border-radius:3px;background:${SC[x.k]};margin-right:8px"></span>${x.n}</td><td class="n">${fN(x.c)}</td><td class="n">${fM(x.a)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No connections for this selection</div>';
  h.push(card('s6','F9','Services by category','',`<select data-sel="f9">${catsAvail.map(([i,l])=>`<option value="${i}" ${i==UI.f9?'selected':''}>${l}</option>`).join('')}</select>`,t9(rowsF9),'f9'));
  /* F10 */
  const rowsF10=D.svcs.map((n,k)=>{let c=0,a=0;for(const i of IX)if(R.s[i]==UI.f10&&R.v[i]==k){c++;a+=R.b[i]}return{n,c,a,k}}).filter(x=>x.c);
  h.push(card('s6','F10','Service by sub-category','',`<select data-sel="f10">${D.subs.map((l,i)=>`<option value="${i}" ${i==UI.f10?'selected':''}>${l}</option>`).join('')}</select>`,t9(rowsF10),'f10'));
  /* F11 F12 */
  const sv=D.svcs.map((n,i)=>({n,i})).filter(x=>byV[x.i].n>0);
  h.push(card('s6','F11','Billed amount by service','',``,bars(sv.map(x=>({n:x.n,v:byV[x.i].b,c:SC[x.i],x:fM(byV[x.i].b),s:fN(byV[x.i].n)+' connections'})))));
  h.push(card('s6','F12','Collection by service','Collected against total billed','',bars(sv.map(x=>({n:x.n,v:byV[x.i].p,u:byV[x.i].b,c:SC[x.i],x:fM(byV[x.i].p),s:'of '+fM(byV[x.i].b),tip:pc(byV[x.i].p,byV[x.i].b)+' collected'})))));
  /* F13..F16 */
  const ar=D.areas.map((n,i)=>({n,i})).filter(x=>byA[x.i].n>0);
  const am=UI.f13,avf=x=>am=='n'?byA[x.i].n:am=='b'?byA[x.i].b:byA[x.i].p,afm=v=>am=='n'?fN(v):fM(v),aT={n:'Consumers by area',b:'Billed amount by area',c:'Collection by area'}[am];
  const OTHI=D.areas.length-1,arS=ar.slice().sort((x,y)=>(x.i==OTHI)-(y.i==OTHI)||avf(y)-avf(x));
  h.push(card('s6','F13',aT,`${ar.length} areas · ${D.meta.period}`,seg('f13',[['n','Consumers'],['b','Billed'],['c','Collection']],am),bars(arS.map(x=>({n:x.n,v:avf(x),c:'var(--a1)',x:afm(avf(x)),s:am=='c'?pc(byA[x.i].p,byA[x.i].b):am=='b'?fN(byA[x.i].n)+' consumers':fM(byA[x.i].b)+' billed',tip:fN(byA[x.i].n)+' consumers · Billed '+fM(byA[x.i].b)+' · Collected '+fM(byA[x.i].p)})),{scroll:1}),'f13'));
  const zn=D.zones.map((n,i)=>({n,i})).filter(x=>byZ[x.i].n>0);
  h.push(card('s6','F14','Consumers by zone',D.meta.period,'',bars(zn.map(x=>({n:x.n,v:byZ[x.i].n,c:'var(--a2)',x:fN(byZ[x.i].n),s:pc(byZ[x.i].n,IX.length)})))));
  h.push(card('s6','F15','Collection by area','Collected against billed','',bars(ar.slice().sort((x,y)=>(x.i==D.areas.length-1)-(y.i==D.areas.length-1)||byA[y.i].p-byA[x.i].p).map(x=>({n:x.n,v:byA[x.i].p,u:byA[x.i].b,c:'var(--a1)',x:fM(byA[x.i].p),s:pc(byA[x.i].p,byA[x.i].b),tip:'Billed '+fM(byA[x.i].b)})),{scroll:1})));
  h.push(card('s6','F16','Collection by zone','Collected against billed','',bars(zn.map(x=>({n:x.n,v:byZ[x.i].p,u:byZ[x.i].b,c:'var(--a2)',x:fM(byZ[x.i].p),s:'of '+fM(byZ[x.i].b),tip:pc(byZ[x.i].p,byZ[x.i].b)+' collected'})))));
  /* F17 F18 marla */
  const ma=D.marlas.map((n,i)=>({n,i})).filter(x=>byM[x.i].n>0);
  const mode=UI.f17,mv=x=>mode=='n'?byM[x.i].n:mode=='b'?byM[x.i].b:byM[x.i].p,mf=v=>mode=='n'?fN(v):fM(v),mT={n:'Consumers by marla',b:'Billed amount by marla',c:'Collection by marla'}[mode];
  h.push(card('s6','F17',mT,'Plot size · group of marla',seg('f17',[['n','Consumers'],['b','Billed'],['c','Collection']],mode),bars(ma.map(x=>({n:x.n+(x.i<7?' marla':''),v:mv(x),c:'var(--a5)',x:mf(mv(x)),s:mode=='c'?pc(byM[x.i].p,byM[x.i].b):mode=='n'?fM(byM[x.i].b)+' billed':fN(byM[x.i].n)+' consumers'}))),'f17'));
  h.push(card('s6','F18','Collection by marla','Collected against billed','',bars(ma.map(x=>({n:x.n+(x.i<7?' marla':''),v:byM[x.i].p,u:byM[x.i].b,c:'var(--a5)',x:fM(byM[x.i].p),s:fN(byM[x.i].paid)+' paid consumers',tip:pc(byM[x.i].p,byM[x.i].b)+' collected'})))));
  /* F19 F20 */
  h.push(card('s6','F19','Total consumers','Who is in this view',``,`<div class="mini" style="margin-bottom:16px"><div><b>${fN(act)}</b><span>Active</span></div><div><b>${fN(ina)}</b><span>Inactive</span></div><div><b>${fN(unm)}</b><span>Not in master file</span></div></div>`+bars([{n:'Paid something',v:pd,c:'var(--good)',x:fN(pd),s:pc(pd,IX.length)},{n:'Paid nothing',v:IX.length-pd,c:'var(--bad)',x:fN(IX.length-pd),s:pc(IX.length-pd,IX.length)}])));
  const bk=[['Up to 500',0,500],['501 – 1,000',500,1000],['1,001 – 5,000',1000,5000],['Above 5,000',5000,1e12]].map(([n,l,u])=>({n,v:0,s:0,l,u}));
  for(const i of IX){const p=R.p[i];if(p>0)for(const b of bk)if(p>b.l&&p<=b.u){b.v++;b.s+=p;break}}
  h.push(card('s6','F20','Paid consumers',`${fN(pd)} consumers · average payment ${pd?fM(P/pd):'—'}`,'',pd?bars(bk.map(b=>({n:b.n,v:b.v,c:'var(--good)',x:fN(b.v),s:fM(b.s)}))):'<div class="empty">No payments in this view</div>'));
  $('#dash').innerHTML=h.join('');
  $('#dash').classList.toggle('hide-tags',!$('#tagsChk').checked);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-seg] button');if(!b)return;const k=b.closest('[data-seg]').dataset.seg;UI[k]=k=='f8'?+b.dataset.k:b.dataset.k;renderDash()});
document.addEventListener('change',e=>{const s=e.target.closest('[data-sel]');if(s){UI[s.dataset.sel]=+s.value;renderDash()}});
/* ===================== shared helpers ===================== */
const ST={cons:{q:'',zone:'',area:'',page:1,per:25,sel:new Set(),dense:false,sort:'',dir:1},exp:{scope:'all',zone:'',areas:new Set(),type:'',status:'',pay:'',mode:'list',topN:100,minBal:'',cf:[],cols:null,colq:'',areaq:'',noPersonal:false,fmt:'xlsx'},col:'ov',cp:'Sep',act:{type:'all',q:''},usr:'users',appr:'pending',apprSel:null,fbForm:'consumer',fbSel:null,fbPrev:false,zoneSel:0,pvRole:1,hist:'all',tg:'zone',ol:'result'};
const hd=(t,d,a='')=>`<div class="head"><div><h1>${t}</h1><p>${d}</p></div><div class="act">${a}</div></div>`;
const dn=(t,pts,links)=>`<div class="dnote"><b>Design note · ${t}</b><ul>${pts.map(p=>`<li>${p}</li>`).join('')}</ul><div>Reference: ${links.map(([l,u])=>`<a href="${u}" target="_blank" rel="noopener">${l}</a>`).join(' · ')}</div></div>`;
const tabs=(key,items,cur)=>`<div class="tabs">${items.map(([k,l,c])=>`<button class="${k==cur?'on':''}" onclick="setST('${key}','${k}')">${l}${c!=null?`<span>${c}</span>`:''}</button>`).join('')}</div>`;
function setST(path,v){const p=path.split('.');let o=ST;for(let i=0;i<p.length-1;i++)o=o[p[i]];o[p[p.length-1]]=v;if(path.startsWith('cons.')&&path!='cons.page'&&path!='cons.dense')ST.cons.page=1;rerender()}
function rr(){const a=document.activeElement,id=a&&a.id,pos=a&&a.selectionStart;rerender();if(id){const e=document.getElementById(id);if(e){e.focus();try{e.setSelectionRange(pos,pos)}catch(_){}}}}
const pill=(t,c='')=>`<span class="pill ${c}">${t}</span>`;
const sw=(on,t,fn='')=>`<button class="sw ${on?'on':''}" onclick="this.classList.toggle('on');${fn||"toast('Saved')"}" aria-label="${t}"></button>`;
const row=(t,d,c)=>`<div class="row"><div class="tx"><b>${t}</b><span>${d}</span></div>${c}</div>`;
