function renderCollection(){
  let B=0,P=0,full=0,part=0,none=0,fb=0,pb=0,nb=0,pd=0;for(const i of ALL){const b=R.b[i],p=R.p[i];B+=b;P+=p;if(p>0)pd++;if(b>0){if(p<=0){none++;nb+=b}else if(p>=b){full++;fb+=b}else{part++;pb+=b}}}
  const byT=grp('t',2,ALL),byZ=grp('z',4,ALL),byV=grp('v',D.svcs.length,ALL),byC=grp('c',D.cats.length,ALL),byA=grp('a',D.areas.length,ALL);
  const tgt=TG.total;let body='';
  if(ST.col=='ov'){body=`<div class="grid">
   <div class="card s4"><div class="ch"><div><h3>Collection efficiency</h3><div class="sub">Paid ÷ billed · ${M.period}</div></div></div><div class="dn" style="justify-content:center">${donut([{n:'Collected',v:P,c:'var(--good)',t:fM(P)},{n:'Outstanding',v:B-P,c:'var(--track)',t:fM(B-P)}],pc(P,B),'collected',170)}</div><div class="mini" style="margin-top:14px;grid-template-columns:1fr 1fr"><div><b>${fM(B)}</b><span>Billed</span></div><div><b>${fM(B-P)}</b><span>Outstanding</span></div></div></div>
   <div class="card s4"><div class="ch"><div><h3>How consumers paid</h3><div class="sub">Of ${fN(full+part+none)} consumers with a bill</div></div></div>${bars([{n:'Paid in full',v:full,c:'var(--good)',x:fN(full),s:pc(full,full+part+none)},{n:'Paid part',v:part,c:'var(--a4)',x:fN(part),s:pc(part,full+part+none)},{n:'Not paid',v:none,c:'var(--bad)',x:fN(none),s:pc(none,full+part+none)}])}<div class="note" style="margin-top:16px">${fN(none)} consumers have paid nothing. Their bills add up to ${fM(nb)}.</div></div>
   <div class="card s4"><div class="ch"><div><h3>Against target</h3><div class="sub">Sample target · change in Settings → Targets</div></div></div><div class="kpi" style="padding:0"><div class="v">${pc(P,tgt)}</div><div class="d">${fM(P)} of ${fM(tgt)}</div></div><div class="meter w"><i style="width:${Math.min(100,100*P/tgt)}%"></i></div><div class="mini" style="margin-top:16px;grid-template-columns:1fr 1fr"><div><b>${fN(pd)}</b><span>Paid consumers</span></div><div><b>${pd?fM(P/pd):'—'}</b><span>Average payment</span></div></div></div>
   ${card('s6','','Collection by zone','Collected against billed','',bars(D.zones.map((n,i)=>({n,v:byZ[i].p,u:byZ[i].b,c:'var(--a2)',x:fM(byZ[i].p),s:pc(byZ[i].p,byZ[i].b)})).filter((x,i)=>byZ[i].n)))}
   ${card('s6','','Collection by category','Commercial categories','',bars(D.cats.map((n,i)=>({n:i?'Category '+n:'Residential',v:byC[i].p,u:byC[i].b,c:'var(--a1)',x:fM(byC[i].p),s:pc(byC[i].p,byC[i].b)})).filter((x,i)=>byC[i].b>0),{scroll:1}))}
   ${card('s6','','Collection by service','Collected against billed','',bars(D.svcs.map((n,i)=>({n,v:byV[i].p,u:byV[i].b,c:SC[i],x:fM(byV[i].p),s:pc(byV[i].p,byV[i].b)})).filter((x,i)=>byV[i].b>0)))}
   <div class="card s6"><div class="ch"><div><h3>Credit balances</h3><div class="sub">Consumers who paid more than billed</div></div></div><div class="kpi" style="padding:0"><div class="v">${fN(M.neg)}</div><div class="d">${fM(M.negsum)} in advance payments. They reduce the total balance, so check them before closing the period.</div></div><div style="margin-top:14px"><button class="btn sm" onclick="toast('Opens the credit list (sample)')">Review credit balances</button></div></div></div>`}
  else{const ar=D.areas.map((n,i)=>({n,i,o:byA[i].b-byA[i].p})).filter(x=>byA[x.i].n).sort((a,b)=>b.o-a.o);
   body=`<div class="grid"><div class="card s5"><div class="ch"><div><h3>Where the money is stuck</h3><div class="sub">Outstanding amount by area</div></div></div>${bars(ar.map(x=>({n:x.n,v:x.o,c:'var(--bad)',x:fM(x.o),s:pc(byA[x.i].n-byA[x.i].paid,byA[x.i].n)+' not paid'})),{scroll:1})}</div>
   <div class="card s7"><div class="ch"><div><h3>Largest balances to follow up</h3><div class="sub">Top 40 outstanding consumers</div></div><div class="r"><button class="btn sm pri" onclick="toast('Reminders queued for 40 consumers (sample)')">Send reminders</button></div></div><div class="tw"><table><thead><tr><th>Consumer</th><th>Area</th><th>Category</th><th class="n">Balance</th></tr></thead><tbody>${D.top.map(r=>`<tr><td><b>${r.name}</b><br><span style="color:var(--mu);font-size:11.5px">${r.no}</span></td><td>${r.area}</td><td>${r.cat}</td><td class="n"><b>${fN(r.bal)}</b></td></tr>`).join('')}</tbody></table></div></div></div>`}
  $('#p-collection').innerHTML=hd('Collection','How much of the bill has been paid, who has not paid, and where to follow up.')+dn('Collection',['Lead with the outcome (efficiency, paid vs not paid) before any breakdown, as in utility operations dashboards.','Payment status is three simple groups: paid in full, paid part, not paid. Each is a number the recovery team can act on.','A separate Recovery tab ranks areas and consumers by what is still owed.'],L('util'))+tabs('col',[['ov','Overview'],['rec','Recovery list']],ST.col)+body}

/* ===================== 1-LINK ===================== */
let OLX=[['2099015877','Allama Iqbal Open University','Unknown amount: paid 300,000 against bill 279,118','Amount mismatch',300000],['2099199999','—','Consumer number not found in master','Unknown consumer',2450],['2099056847','Ali Raza','Same transaction ID appears twice in the file','Duplicate',1450],['2099030112','Mr Imran','Paid on a consumer marked inactive','Inactive consumer',690]];
function resolveEx(i,w){OLX.splice(i,1);logAct('upload',w+' a 1-Link exception','Sample file');toast(w);rerender()}
function renderOneLink(){const P=R.p.reduce((a,b)=>a+b,0);
  $('#p-onelink').innerHTML=hd('1-Link update','Bring daily 1-Link payment files in and post them against consumer numbers.','<button class="btn pri" onclick="toast(\'Sync queued (sample)\')">Sync now</button>')+
  dn('1-Link update',['Four visible stages (upload, validate, match, post) so the user always knows what step a file is on.','Anything that cannot match goes to an exception queue with a reason, instead of failing the whole file.','Counts always add up: rows read = matched + needs review + rejected.'],L('exc','upl'))+
  `<div class="stp"><div class="on"><b>1 · Upload</b><span>Choose the 1-Link file</span></div><div><b>2 · Validate</b><span>Columns, dates, duplicates</span></div><div><b>3 · Match</b><span>Consumer number lookup</span></div><div><b>4 · Post</b><span>Update paid and balance</span></div></div>
  <div class="grid"><div class="card s5"><h3>Upload a 1-Link file</h3><div class="sub" style="margin-bottom:12px">.xlsx, .csv or the bank's .txt layout</div><div class="drop" data-drop><b style="color:var(--tx)">Drop the 1-Link file here</b><br>or <u>browse</u><input type="file" hidden></div><div data-files></div>
   <h3 style="margin:20px 0 8px">Columns we expect</h3><table><tbody>${[['CONSUMER_NO','Required · 10 digits'],['PAID_AMOUNT','Required · number'],['PAYMENT_DATE','Required · date'],['BANK','Optional'],['TXN_ID','Required · must be unique']].map(x=>`<tr><td><b>${x[0]}</b></td><td style="color:var(--mu)">${x[1]}</td></tr>`).join('')}</tbody></table><div class="note" style="margin-top:12px">Proposed layout. Send me a real 1-Link file and I will match these columns to it.</div></div>
  <div class="card s7"><div class="ch"><div><h3>Latest file</h3><div class="sub">Sample result so you can see the screen</div></div><div class="r">${pill('Sample data','y')}</div></div>
   <div class="mini" style="grid-template-columns:repeat(4,1fr)"><div><b>1,284</b><span>Rows read</span></div><div><b style="color:var(--good)">1,261</b><span>Matched</span></div><div><b style="color:var(--a4)">${OLX.length+15}</b><span>Needs review</span></div><div><b style="color:var(--bad)">4</b><span>Rejected</span></div></div>
   <h3 style="margin:20px 0 8px">Needs review (${OLX.length} shown)</h3>${OLX.length?`<div class="tw" style="max-height:340px"><table><thead><tr><th>Consumer</th><th>Reason</th><th class="n">Amount</th><th></th></tr></thead><tbody>${OLX.map((x,i)=>`<tr><td><b>${x[0]}</b><br><span style="color:var(--mu);font-size:11.5px">${x[1]}</span></td><td>${pill(x[3],'y')}<br><span style="color:var(--mu);font-size:11.5px">${x[2]}</span></td><td class="n">${fN(x[4])}</td><td><button class="btn sm" onclick="resolveEx(${i},'Posted')">Post</button> <button class="btn sm bad" onclick="resolveEx(${i},'Rejected')">Reject</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nothing left to review. You can post the file to collection.</div>'}
   <div style="margin-top:14px;display:flex;gap:8px"><button class="btn pri" ${OLX.length?'disabled':''} onclick="toast('File posted to collection (sample)')">Post file to collection</button></div></div>
  <div class="card s12"><h3>File history</h3><div class="tw" style="margin-top:10px"><table><thead><tr><th>File</th><th>Received</th><th class="n">Rows</th><th class="n">Matched</th><th class="n">Amount</th><th>Status</th></tr></thead><tbody>${[['1LINK_20261108.xlsx','8 Nov 2026','1,284','1,261','Rs 1.9M','Needs review'],['1LINK_20261107.xlsx','7 Nov 2026','1,102','1,102','Rs 1.6M','Posted'],['1LINK_20261106.xlsx','6 Nov 2026','1,455','1,451','Rs 2.2M','Posted']].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td class="n">${x[2]}</td><td class="n">${x[3]}</td><td class="n">${x[4]}</td><td>${pill(x[5],x[5]=='Posted'?'g':'y')}</td></tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:10px">File history is sample data. Payments already in the September bill report add up to ${fM(P)}.</div></div></div>`}

/* ===================== CLOSED PERIODS ===================== */
const CPS={Sep:{closed:false}};
const MON=['Oct','Sep','Aug','Jul','Jun','May','Apr','Mar','Feb','Jan'];
function closeChecks(){let B=0,P=0,bal=0;for(const i of ALL){B+=R.b[i];P+=R.p[i]}
  const pend=APPR.filter(a=>a.status=='pending').length;
  return [['Consumer master uploaded',M.f2+' · '+fN(M.master)+' consumers','ok',1],['Bill collection report uploaded',M.f1+' · '+fN(M.billrows)+' rows','ok',1],
   ['Totals tally','Billed − paid = balance ('+fM(B)+' − '+fM(P)+' = '+fM(B-P)+')','ok',1],
   ['Approvals cleared',pend?pend+' change requests are still waiting':'No requests waiting',pend?'warn':'ok',1],
   ['Every billed consumer is in the master',M.billonly+' billed consumers have no master record','warn',0],['Active consumers without a bill',fN(M.masteronly_active)+' active consumers were not billed','warn',0],
   ['Credit balances reviewed',fN(M.neg)+' consumers are in credit ('+fM(M.negsum)+')','warn',0],['1-Link payments posted','No 1-Link file posted for this period yet','todo',0]]}
function renderClosed(){const sel=ST.cp,isSep=sel=='Sep',cl=CPS.Sep.closed;
  const ch=closeChecks(),req=ch.filter(c=>c[3]),ready=req.every(c=>c[2]=='ok');
  let B=0,P=0;for(const i of ALL){B+=R.b[i];P+=R.p[i]}
  const list=MON.map(m=>{const s=m=='Sep'?(cl?'Closed':'Ready to review'):m=='Oct'?'Open':'No data';return `<button class="${sel==m?'on':''}" onclick="setST('cp','${m}')"><div style="flex:1"><b>${m}-2026</b><small>${s}</small></div>${m=='Sep'?pill(cl?'Locked':'Open',cl?'g':'y'):''}</button>`}).join('');
  let right;
  if(isSep)right=`<div class="card" style="margin-bottom:16px"><div class="ch"><div><h3>Sep-2026</h3><div class="sub">${cl?'Closed and locked. Bills and payments cannot be edited.':'Open. Bills and payments can still change.'}</div></div><div class="r">${cl?`<button class="btn sm" onclick="reopenReq()">Request reopen</button>`:`<button class="btn pri" ${ready?'':'disabled'} onclick="confirmClose()">Close period</button>`}</div></div>
   <div class="mini"><div><b>${fN(N)}</b><span>Billed consumers</span></div><div><b>${fM(B)}</b><span>Billed</span></div><div><b>${fM(P)}</b><span>Collected (${pc(P,B)})</span></div></div></div>
   <div class="card"><div class="ch"><div><h3>Before you close</h3><div class="sub">${req.filter(c=>c[2]=='ok').length} of ${req.length} required checks done · other checks are advice only</div></div></div><div class="meter"><i style="width:${100*req.filter(c=>c[2]=='ok').length/req.length}%"></i></div>
   ${ch.map(c=>`<div class="ck"><div class="ico ${c[2]}">${c[2]=='ok'?'✓':c[2]=='warn'?'!':'·'}</div><div class="tx"><b>${c[0]}</b> ${c[3]?pill('Required'):''}<span>${c[1]}</span></div>${c[0]=='Approvals cleared'&&c[2]!='ok'?`<a class="btn sm" href="#settings/approvals">Review</a>`:''}</div>`).join('')}</div>`;
  else right=`<div class="card"><div class="empty"><b style="color:var(--tx);font-size:16px">${sel}-2026 has no data yet</b><br>Upload the bill collection report for this month to start its checklist.<br><br><a class="btn pri" href="#upload">Upload data</a></div></div>`;
  $('#p-closed').innerHTML=hd('Closed period data','A closed period is locked. Nobody can change its bills or payments.')+dn('Closed period data',['A checklist decides when a period is ready: required checks must pass, advice-only checks warn but do not block (same split as month-end close tools).','Locking makes the numbers permanent for reporting; reopening is a deliberate request, not a button anyone can press.','Each check shows its own number, so the user can fix the cause instead of guessing.'],L('close','lock'))+
  `<div class="grid"><div class="card s4"><h3 style="margin-bottom:10px">Periods · 2026</h3><div class="plist">${list}</div></div><div class="s8">${right}</div></div>`}
function confirmClose(){openModal(`<h3 style="font-size:18px">Close Sep-2026?</h3><p style="color:var(--mu);margin:10px 0 18px">Bills and payments for this period will be locked. Reopening later needs an administrator's approval.</p><div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn" onclick="closeAll()">Cancel</button><button class="btn pri" onclick="doClose()">Close period</button></div>`)}
function doClose(){CPS.Sep.closed=true;logAct('settings','closed the period','Sep-2026','Period locked after 4 required checks passed');closeAll();toast('Sep-2026 closed and locked');rerender()}
function reopenReq(){CPS.Sep.closed=false;logAct('approval','reopened the period','Sep-2026');toast('Reopened (sample)');rerender()}

