ACT.push(...[
 {t:'approval',who:'Data Entry Operator',act:'asked to change a category',obj:'2099015877',day:'8 Nov 2026',time:'16:20',detail:'Category A → A1 · Sample entry'},
 {t:'user',who:'Profile Name',act:'invited a user',obj:'Auditor',day:'8 Nov 2026',time:'11:05',detail:'Role: Viewer · Sample entry'},
 {t:'settings',who:'Profile Name',act:'changed the monthly target',obj:'Zone 3',day:'7 Nov 2026',time:'15:42',detail:'Rs 8,000,000 → Rs 8,500,000 · Sample entry'},
 {t:'security',who:'Revenue Officer 2',act:'signed in from a new device',obj:'Kasur',day:'7 Nov 2026',time:'09:12',detail:'Chrome on Windows · Sample entry'},
 {t:'settings',who:'Profile Name',act:'turned on CNIC masking',obj:'Privacy',day:'6 Nov 2026',time:'17:30',detail:'Applies to Revenue officer and Viewer roles · Sample entry'}]);
const TCOL={upload:'var(--a1)',approval:'var(--a4)',settings:'var(--a5)',security:'#e0566a',user:'var(--a2)'},TL={upload:'Uploads',approval:'Approvals',settings:'Settings',security:'Security',user:'Users'};
function renderAct(){const s=ST.act,q=s.q.toLowerCase();const l=ACT.filter(e=>(s.type=='all'||e.t==s.type)&&(!q||(e.who+e.act+e.obj+(e.detail||'')).toLowerCase().includes(q)));
  const days=[...new Set(l.map(e=>e.day))];
  $('#p-activities').innerHTML=hd('Activities','Every upload, approval and setting change, newest first.','<button class="btn" onclick="toast(\'Export is part of the full build\')">Export log</button>')+
  dn('Activities',['Each line says who did what to which record, with the exact time. Click a line for the before and after.','Entries are added by the system and cannot be edited or deleted.','Filter by type or search; days group the list so a long history stays readable.'],L('audit'))+
  `<div class="grid"><div class="card s8"><div class="tb"><button class="chip ${s.type=='all'?'on':''}" onclick="setST('act.type','all')">All<span>${ACT.length}</span></button>${Object.keys(TL).map(k=>`<button class="chip ${s.type==k?'on':''}" onclick="setST('act.type','${k}')">${TL[k]}<span>${ACT.filter(e=>e.t==k).length}</span></button>`).join('')}<span class="sp"></span><input type="text" id="aq" placeholder="Search activity" value="${s.q}" oninput="ST.act.q=this.value;rr()"></div>
  ${l.length?days.map(d=>`<div class="day">${d}</div>`+l.filter(e=>e.day==d).map(e=>`<div class="ev" onclick="this.classList.toggle('open')"><div class="ei" style="background:${TCOL[e.t]}">${ini(e.who)}</div><div class="tx"><b>${e.who}</b> ${e.act} <b>${e.obj}</b><br><small>${e.time}</small><div class="dt">${e.detail||'No further detail'}</div></div></div>`).join('')).join(''):'<div class="empty">No activity matches. Clear the search or pick another type.</div>'}</div>
  <div class="card s4"><h3>By type</h3>${bars(Object.keys(TL).map(k=>({n:TL[k],v:ACT.filter(e=>e.t==k).length,c:TCOL[k],x:ACT.filter(e=>e.t==k).length})))}<div class="note" style="margin-top:16px">The first two entries are your two files. The rest are sample entries to show the layout.</div></div></div>`}

/* ===================== UPLOAD ===================== */
document.addEventListener('change',e=>{if(e.target.type=='file'&&e.target.closest('.drop')){addFile(e.target.closest('.drop'),e.target.files[0])}});
document.addEventListener('click',e=>{const d=e.target.closest('[data-drop]');if(d&&e.target.tagName!='INPUT')d.querySelector('input').click()});
['dragover','drop'].forEach(ev=>document.addEventListener(ev,e=>{const d=e.target.closest('[data-drop]');if(!d)return;e.preventDefault();d.classList.toggle('over',ev=='dragover');if(ev=='drop')addFile(d,e.dataTransfer.files[0])}));
function addFile(d,f){if(!f)return;const t=d.parentElement.querySelector('[data-files]');t.innerHTML=`<div class="file"><b>${f.name}</b><span style="color:var(--mu)">${(f.size/1048576).toFixed(1)} MB · ready to validate</span></div>`;toast('File selected. Reading it runs in the full build.')}

